pub fn cw(cb: &mut [u8], o: &mut [i32], x: i32, y: i32, mode: i32) -> i32 {
    // Write the canonical form (mode 0 DC, 1 EC) of the CHECKED item at cb[x]
    // to cb[y, ...), where y is past the item; answers the form's end, or -1
    // when cb or the record stack in o is too small. EC sorts a map's pairs
    // by their keys' EC bytes (no two are equal: the map was checked).
    let ib: i32 = cb[(x) as usize] as i32;
    let major: i32 = (i32::cast_unsigned(ib) >> 5).cast_signed();
    let ai: i32 = ib & 31;
    let n: i32 = cb.len() as i32;
    if major == 7 {
        if (ai >= 25) && (ai <= 27) {
            return cw_float(cb, x, y, mode);
        }
        if ai == 24 {
            if (y + 2) > n {
                return -1;
            }
            let v: i32 = cb[(x + 1) as usize] as i32;
            cb[(y) as usize] = (ib) as u8;
            cb[(y + 1) as usize] = (v) as u8;
            return y + 2;
        }
        if y >= n {
            return -1;
        }
        cb[(y) as usize] = (ib) as u8;
        return y + 1;
    }
    let mut q: i32 = targ(cb, o, x);
    let hi: i32 = o[(O_HI) as usize];
    let lo: i32 = o[(O_LO) as usize];
    if major <= 1 {
        return put_head(cb, y, major, hi, lo);
    }
    if major == 6 {
        let y6: i32 = put_head(cb, y, 6, hi, lo);
        if y6 < 0 {
            return y6;
        }
        return cw(cb, o, q, y6, mode);
    }
    if major <= 3 {
        if ai != 31 {
            let y2: i32 = put_head(cb, y, major, 0, lo);
            if (y2 < 0) || ((y2 + lo) > n) {
                return -1;
            }
            return move_within(cb, q, y2, lo);
        }
        let total: i32 = tlength(cb, o, x);
        let mut y3: i32 = put_head(cb, y, major, 0, total);
        if (y3 < 0) || ((y3 + total) > n) {
            return -1;
        }
        while (cb[(q) as usize] as i32) != 255 {
            q = targ(cb, o, q);
            let cl: i32 = o[(O_LO) as usize];
            y3 = move_within(cb, q, y3, cl);
            q += cl;
        }
        return y3;
    }
    let mut cnt: i32;
    if ai == 31 {
        cnt = tcount(cb, o, q);
        if major == 5 {
            cnt = cnt >> 1;
        }
    } else {
        cnt = lo;
    }
    if (major == 4) || ((mode == 0) || (cnt < 2)) {
        let mut y4: i32 = put_head(cb, y, major, 0, cnt);
        let mut k: i32 = cnt;
        if major == 5 {
            k = 2 * cnt;
        }
        for _i in 0..k {
            if y4 < 0 {
                return y4;
            }
            y4 = cw(cb, o, q, y4, mode);
            q = tskip(cb, o, q);
        }
        return y4;
    }
    // EC map of two or more pairs: the pairs' forms after a 9-byte gap, a
    // record (key form, key length, pair end) each, sorted; then the head
    // and the pairs in order after them, moved down to y.
    let r0: i32 = o[(O_S_RTOP) as usize];
    let mut t: i32 = y + 9;
    if (r0 + (3 * cnt)) > o[(O_S_DLOW) as usize] {
        return -1;
    }
    o[(O_S_RTOP) as usize] = r0 + (3 * cnt);
    for i in 0..cnt {
        let ks: i32 = t;
        let ke: i32 = cw(cb, o, q, t, mode);
        if ke < 0 {
            o[(O_S_RTOP) as usize] = r0;
            return ke;
        }
        q = tskip(cb, o, q);
        let ve: i32 = cw(cb, o, q, ke, mode);
        if ve < 0 {
            o[(O_S_RTOP) as usize] = r0;
            return ve;
        }
        q = tskip(cb, o, q);
        o[(r0 + (3 * i)) as usize] = ks;
        o[((r0 + (3 * i)) + 1) as usize] = ke - ks;
        o[((r0 + (3 * i)) + 2) as usize] = ve;
        t = ve;
    }
    let u0: i32 = o[(O_S_UNITS) as usize];
    rsort(cb, cb, o, r0, cnt, 0);
    // the inner sort is part of writing a form: not a duplicate-check charge
    o[(O_S_UNITS) as usize] = u0;
    let mut z: i32 = put_head(cb, t, 5, 0, cnt);
    if z < 0 {
        o[(O_S_RTOP) as usize] = r0;
        return z;
    }
    for j in 0..cnt {
        let rj: i32 = r0 + (3 * j);
        let ps: i32 = o[(rj) as usize];
        let pe: i32 = o[(rj + 2) as usize];
        if (z + (pe - ps)) > n {
            o[(O_S_RTOP) as usize] = r0;
            return -1;
        }
        z = move_within(cb, ps, z, pe - ps);
    }
    o[(O_S_RTOP) as usize] = r0;
    return move_within(cb, t, y, z - t);
}
pub fn dup_pairs(b: &[u8], o: &mut [i32], q0: i32, npairs: i32) -> i32 {
    // The pairs of a CHECKED map whose first key is at q0: npairs, or for an
    // indefinite map (npairs -1) half the items before its break.
    if npairs >= 0 {
        return npairs;
    }
    return tcount(b, o, q0) >> 1;
}
pub fn dup_room(o: &mut [i32], n: i32) -> i32 {
    // Push n records (0), or -CODE_SCRATCH with o[O_VNEEDW] raised.
    let r0: i32 = o[(O_S_RTOP) as usize];
    if (r0 + (3 * n)) > o[(O_S_DLOW) as usize] {
        o[(O_VNEEDW) as usize] = (o.len() as i32) + ((3 * n) + 64);
        return -CODE_SCRATCH;
    }
    o[(O_S_RTOP) as usize] = r0 + (3 * n);
    return 0;
}
pub fn dup_input(b: &[u8], o: &mut [i32], q0: i32, n: i32) -> i32 {
    // Records for the n pairs from q0 when every key is canonical and not
    // EC-sensitive (its input bytes are its form): 0; 1 (records popped) when
    // some key needs its EC form written; or -CODE_SCRATCH.
    let g: i32 = dup_room(o, n);
    if g < 0 {
        return g;
    }
    let r0: i32 = o[(O_S_RTOP) as usize] - (3 * n);
    let mut q: i32 = q0;
    for i in 0..n {
        let ke: i32 = tskip(b, o, q);
        let rr: i32 = r0 + (3 * i);
        if kclass(b, o, q) != 0 {
            o[(O_S_RTOP) as usize] = r0;
            return 1;
        }
        o[(rr) as usize] = (-1) - q;
        o[(rr + 1) as usize] = ke - q;
        o[(rr + 2) as usize] = q;
        q = tskip(b, o, ke);
    }
    return 0;
}
pub fn dup_forms(b: &[u8], o: &mut [i32], cb: &mut [u8], q0: i32, n: i32) -> i32 {
    // Records for the n pairs from q0, writing the EC form of every key that
    // is not canonical or is EC-sensitive into cb from o[O_S_CBTOP] (the key's
    // bytes first, its form after them). 0, or -CODE_SCRATCH with o[O_VNEEDW] /
    // o[O_VNEEDB] raised (nothing left pushed).
    let g: i32 = dup_room(o, n);
    if g < 0 {
        return g;
    }
    let r0: i32 = o[(O_S_RTOP) as usize] - (3 * n);
    let cb0: i32 = o[(O_S_CBTOP) as usize];
    let mut ctop: i32 = cb0;
    let mut q: i32 = q0;
    for i in 0..n {
        let ke: i32 = tskip(b, o, q);
        let rr: i32 = r0 + (3 * i);
        if kclass(b, o, q) == 0 {
            o[(rr) as usize] = (-1) - q;
            o[(rr + 1) as usize] = ke - q;
        } else {
            let kl: i32 = ke - q;
            if (ctop + kl) > (cb.len() as i32) {
                o[(O_S_RTOP) as usize] = r0;
                o[(O_VNEEDB) as usize] = (cb.len() as i32) + (4 * (kl + 64));
                return -CODE_SCRATCH;
            }
            for j in 0..kl {
                let v: i32 = b[(q + j) as usize] as i32;
                cb[(ctop + j) as usize] = (v) as u8;
            }
            let fe: i32 = cw(cb, o, ctop, ctop + kl, 1);
            if fe < 0 {
                o[(O_S_RTOP) as usize] = r0;
                o[(O_VNEEDB) as usize] = (cb.len() as i32) + (4 * (kl + 64));
                o[(O_VNEEDW) as usize] = (o.len() as i32) + 64;
                return -CODE_SCRATCH;
            }
            o[(rr) as usize] = ctop + kl;
            o[(rr + 1) as usize] = fe - (ctop + kl);
            ctop = fe;
        }
        o[(rr + 2) as usize] = q;
        q = tskip(b, o, ke);
    }
    o[(O_S_CBTOP) as usize] = ctop;
    return 0;
}
pub fn dup_forms_within(cb: &mut [u8], o: &mut [i32], q0: i32, n: i32) -> i32 {
    // dup-forms for a map that is itself in cb (inside a gathered payload,
    // below o[O_S_CBTOP]): the same records, the forms written after it.
    let g: i32 = dup_room(o, n);
    if g < 0 {
        return g;
    }
    let r0: i32 = o[(O_S_RTOP) as usize] - (3 * n);
    let mut ctop: i32 = o[(O_S_CBTOP) as usize];
    let mut q: i32 = q0;
    for i in 0..n {
        let ke: i32 = tskip(cb, o, q);
        let rr: i32 = r0 + (3 * i);
        if kclass(cb, o, q) == 0 {
            o[(rr) as usize] = (-1) - q;
            o[(rr + 1) as usize] = ke - q;
        } else {
            let kl: i32 = ke - q;
            if (ctop + kl) > (cb.len() as i32) {
                o[(O_S_RTOP) as usize] = r0;
                o[(O_VNEEDB) as usize] = (cb.len() as i32) + (4 * (kl + 64));
                return -CODE_SCRATCH;
            }
            move_within(cb, q, ctop, kl);
            let fe: i32 = cw(cb, o, ctop, ctop + kl, 1);
            if fe < 0 {
                o[(O_S_RTOP) as usize] = r0;
                o[(O_VNEEDB) as usize] = (cb.len() as i32) + (4 * (kl + 64));
                o[(O_VNEEDW) as usize] = (o.len() as i32) + 64;
                return -CODE_SCRATCH;
            }
            o[(rr) as usize] = ctop + kl;
            o[(rr + 1) as usize] = fe - (ctop + kl);
            ctop = fe;
        }
        o[(rr + 2) as usize] = q;
        q = tskip(cb, o, ke);
    }
    o[(O_S_CBTOP) as usize] = ctop;
    return 0;
}
pub fn dup_finish(b: &[u8], cbr: &[u8], o: &mut [i32], n: i32, cb0: i32) -> i32 {
    // The top n records (built by dup-input or dup-forms, or retained by a
    // session): 1 unit each, the heap sort by form (ties by offset), then the
    // neighbours, each comparison ceil(min/64) units (o[O_S_UNITS]); pops
    // them and resets o[O_S_CBTOP] to cb0. 0, or duplicate_key at the
    // earliest second occurrence: the smallest offset of a key equal to an
    // earlier one. cbr holds the forms at addresses >= 0 (any buffer when
    // there are none).
    let r0: i32 = o[(O_S_RTOP) as usize] - (3 * n);
    let mut best: i32 = -1;
    let mut eqprev: bool = false;
    o[(O_S_UNITS) as usize] = o[(O_S_UNITS) as usize] + n;
    rsort(b, cbr, o, r0, n, 1);
    for k in 1..n {
        let c: i32 = rcmp(b, cbr, o, r0 + (3 * (k - 1)), r0 + (3 * k), 0);
        if c == 0 {
            if !eqprev {
                let off: i32 = o[((r0 + (3 * k)) + 2) as usize];
                if (best < 0) || (off < best) {
                    best = off;
                }
            }
            eqprev = true;
        } else {
            eqprev = false;
        }
    }
    o[(O_S_RTOP) as usize] = r0;
    o[(O_S_CBTOP) as usize] = cb0;
    if best >= 0 {
        return fail(o, best, CODE_DUPLICATE_KEY);
    }
    return 0;
}
pub fn gather(b: &[u8], o: &mut [i32], cb: &mut [u8], x: i32, y: i32) -> i32 {
    // The content of the CHECKED string item at x (any length kind) into
    // cb[y, ...): answers its end, or -1 when cb is too short.
    let ai: i32 = (b[(x) as usize] as i32) & 31;
    let mut q: i32 = targ(b, o, x);
    let mut z: i32 = y;
    if ai != 31 {
        let l: i32 = o[(O_LO) as usize];
        if (y + l) > (cb.len() as i32) {
            return -1;
        }
        for j in 0..l {
            let v: i32 = b[(q + j) as usize] as i32;
            cb[(y + j) as usize] = (v) as u8;
        }
        return y + l;
    }
    while (b[(q) as usize] as i32) != 255 {
        q = targ(b, o, q);
        let l2: i32 = o[(O_LO) as usize];
        if (z + l2) > (cb.len() as i32) {
            return -1;
        }
        for j2 in 0..l2 {
            let v2: i32 = b[(q + j2) as usize] as i32;
            cb[(z + j2) as usize] = (v2) as u8;
        }
        z += l2;
        q += l2;
    }
    return z;
}
pub fn gather_within(cb: &mut [u8], o: &mut [i32], x: i32, y: i32) -> i32 {
    // gather for a string item that is itself in cb, before y.
    let ai: i32 = (cb[(x) as usize] as i32) & 31;
    let mut q: i32 = targ(cb, o, x);
    let mut z: i32 = y;
    if ai != 31 {
        let l: i32 = o[(O_LO) as usize];
        if (y + l) > (cb.len() as i32) {
            return -1;
        }
        return move_within(cb, q, y, l);
    }
    while (cb[(q) as usize] as i32) != 255 {
        q = targ(cb, o, q);
        let l2: i32 = o[(O_LO) as usize];
        if (z + l2) > (cb.len() as i32) {
            return -1;
        }
        z = move_within(cb, q, z, l2);
        q += l2;
    }
    return z;
}
pub fn dc_copy(b: &[u8], o: &mut [i32], cb: &mut [u8]) -> i32 {
    // The DC form of the CHECKED document b (the codec's copy of valid input that
    // is not its own DC form, D262): b copied to cb[0, n), cw's mode 0 after it.
    // Answers the form's end (the form is cb[n, end)), or -1 when cb is too
    // short (2n + n/128 + 64 bytes always suffice).
    let n: i32 = b.len() as i32;
    if n > (cb.len() as i32) {
        return -1;
    }
    cb[(0) as usize..((0) + (n)) as usize].copy_from_slice(&b[(0) as usize..((0) + (n)) as usize]);
    return cw(cb, o, 0, n, 0);
}
